'use client'

import * as React from 'react'
import {
  cn,
  tableBodyVariants,
  tableCaptionVariants,
  tableCellVariants,
  tableFooterVariants,
  tableHeaderVariants,
  tableHeadVariants,
  tableRowVariants,
  tableVariants,
} from "@/lib/utils"

function Table({ className, ...props }: React.ComponentProps<'table'>) {
  return (
    <div className="relative w-full overflow-auto">
      <table data-slot="table" className={cn(tableVariants(), className)} {...props} />
    </div>
  )
}

function TableHeader({ className, ...props }: React.ComponentProps<'thead'>) {
  return (
    <thead data-slot="table-header" className={cn(tableHeaderVariants(), className)} {...props} />
  )
}

function TableBody({ className, ...props }: React.ComponentProps<'tbody'>) {
  return <tbody data-slot="table-body" className={cn(tableBodyVariants(), className)} {...props} />
}

function TableFooter({ className, ...props }: React.ComponentProps<'tfoot'>) {
  return (
    <tfoot data-slot="table-footer" className={cn(tableFooterVariants(), className)} {...props} />
  )
}

function TableRow({ className, ...props }: React.ComponentProps<'tr'>) {
  return <tr data-slot="table-row" className={cn(tableRowVariants(), className)} {...props} />
}

function TableHead({ className, ...props }: React.ComponentProps<'th'>) {
  return <th data-slot="table-head" className={cn(tableHeadVariants(), className)} {...props} />
}

function TableCell({ className, ...props }: React.ComponentProps<'td'>) {
  return <td data-slot="table-cell" className={cn(tableCellVariants(), className)} {...props} />
}

function TableCaption({ className, ...props }: React.ComponentProps<'caption'>) {
  return (
    <caption
      data-slot="table-caption"
      className={cn(tableCaptionVariants(), className)}
      {...props}
    />
  )
}

export { Table, TableBody, TableCaption, TableCell, TableFooter, TableHead, TableHeader, TableRow }

.tk-table {
  border: 1px solid #e4e4e7;
  border-radius: 12rpx;
  overflow: hidden;
  background: #fff;
}
.tk-table-row {
  display: flex;
  padding: 12rpx;
  border-bottom: 1px solid #f4f4f5;
}
.tk-table-row:last-child {
  border-bottom: none;
}
.tk-table-head {
  background: #fafafa;
  font-weight: 600;
}
.tk-cell {
  flex: 1;
  font-size: 28rpx;
  color: #09090b;
}
.tk-right {
  text-align: right;
}
.tk-status {
  border-radius: 9999rpx;
  padding: 4rpx 12rpx;
  font-size: 24rpx;
}
.tk-ok {
  background: #ecfdf3;
  color: #047857;
}
.tk-warn {
  background: #fef9c3;
  color: #92400e;
}

{
    "component": true
}

import { tableBodyVariants } from '../utils'

Component({
  options: {
    styleIsolation: "apply-shared",
  },
    externalClasses: ['ext-class'],
    properties: {
        extClass: { type: String, value: '' }
    },
    data: {
        className: ''
    },
    observers: {
        extClass: function (extClass) {
            this.setData({
                className: tableBodyVariants({ className: extClass })
            })
        }
    }
})

